  -- typed one would otherwise still be ambiguous.
  (select v.id from public.visa_source_versions v
     join public.visa_sources s on s.id = v.source_id
    where s.source_url = 'https://aima.gov.pt/pt/viver/reagrupamento-familiar-com-familiar-fora-de-territorio-nacional-art-98-o-n-o-1'
      and v.is_active
      and (s.visa_type_id is null
           or s.visa_type_id = (select id from public.visa_types
                                 where visaai_id = 'pt-reagrupamento-familiar-fora'))
    order by s.visa_type_id nulls last
    limit 1),
  'autorização escrita do progenitor não residente autenticada por autoridade consular portuguesa ou cópia da decisão que atribui a confiança legal do filho e/ou da filha menor ou a tutela do incapaz ao residente ou ao seu cônjuge', 'Autorização escrita do progenitor não residente autenticada por autoridade consular portuguesa ou cópia da decisão que atribui a confiança legal do filho e/ou da filha menor ou a tutela do incapaz ao residente ou ao seu cônjuge', 'manual', 1.00,
